def speak(ref,contains,speaker,hi,en):
 matches=[x for pg in pages for row in pg['rows'] for x in row if x['sourcePanel']==ref and contains in x['beat']]
 assert len(matches)==1,(ref,contains,len(matches))
 matches[0].update(mode='dialogue',speaker=speaker,draftHi=hi,draftEn=en)
speak('bk-04-05','Brahma urges','Brahma','राम के कार्य में सहायक वानर-वीरों को जन्म दो।','Bring forth vanara heroes to help Rama.')
