for page in pages:
 page['sourceSargas']=sorted({s for row in page['rows'] for x in row for s in source[x['sourcePanel']]['sargas']})
 page['currentPages']=sorted({source[x['sourcePanel']]['currentPage'] for row in page['rows'] for x in row})
 page['episodes']=list(dict.fromkeys(source[x['sourcePanel']]['episode'] for row in page['rows'] for x in row))
 page['entryContext']=('Start: Valmiki and Narada at the hermitage.' if page['number']==1 else pages[page['number']-2]['transitionToNext'])
 page['scrollTarget']={'minimal':{'standardViewportRange':[.90,1.15],'largeViewportRange':[1.0,1.35]},'gentle':{'standardViewportRange':[1.05,1.35],'largeViewportRange':[1.15,1.60]},'natural':{'standardViewportRange':[1.20,1.60],'largeViewportRange':[1.35,1.85]}}[page['scrollClass']]
 page['scrollTarget']['status']='Authoring target including live text, not a measurement or hard cap; readability/complete artwork wins.'
 page['captionPolicy']='Short time/place/cause captions only; action shown by art. Aim for at most two caption blocks per page plus name/time labels; a complex genealogy/legend may need more, and must be reviewed rather than silently dropping facts. Do not place the full old narration above every frame.'
 page['rowPlans']=[dict(row=ri,columns=len(row),preferredArtAspect=('4:5 complete hero' if len(page['rows'])==1 else ('9:10 per complete paired scene' if len(row)==2 else ('3:2 complete wide scene' if len(page['rows'])==2 else '7:4 complete wide scene'))),readingOrder='Left to right within this row, then down',height='Content-led, equal frame bottoms within row; live text may grow the page') for ri,row in enumerate(page['rows'],1)]
 page['dialogueBalloonCount']=sum(x['mode']=='dialogue' for row in page['rows'] for x in row)
 for ri,row in enumerate(page['rows'],1):
  for ci,x in enumerate(row,1):
   ref=x['sourcePanel'];seen[ref]+=1;x['id']=ref if seen[ref]==1 else ref+f'-shot-{seen[ref]}'
   x['row']=ri;x['column']=ci;x['source']=source[ref]['source'];x['sourceSargas']=source[ref]['sargas']
   x['artWork']='Recompose complete scene for row geometry; no caption-driven cropping.' if len(row)>1 or seen[ref]>1 or page['rowCount']==1 else 'Retain full reviewed frame if legible at planned width; otherwise recompose.'
   if x['mode']=='dialogue' and x['draftHi']!=source[ref]['hi'].get('dialogue'):
    x['artWork']='Compose a visible, correctly identified speaker shot for this draft line; retain complete context/action. The current reference image is not automatically suitable for the new balloon.'
   x['textStatus']='Planning paraphrase from existing sourced retelling; primary-passage and two-publication editorial comparison pending.' if x['mode'] in ['dialogue','teller-caption'] else 'Preserve source facts; final concise caption/translation to be authored after page plan acceptance.'
   assignments[ref].append(dict(page=page['number'],row=ri,column=ci,shot=x['id'],mode=x['mode']))
assert set(assignments)==set(source),(set(source)-set(assignments),set(assignments)-set(source))
